<template><div class="page"><div class="head"><div><h2>服务工单</h2><p>统一处理留言、注销、反馈、纠错与投诉建议</p></div><el-button @click="load">刷新</el-button></div>
<div class="filters"><el-input v-model="query.keyword" placeholder="工单号、标题或内容" clearable/><el-select v-model="query.type" clearable placeholder="工单类型"><el-option v-for="(v,k) in types" :key="k" :label="v" :value="k"/></el-select><el-select v-model="query.status" clearable placeholder="状态"><el-option v-for="(v,k) in statuses" :key="k" :label="v" :value="k"/></el-select><el-button type="primary" @click="load">查询</el-button></div>
<el-table :data="list" v-loading="loading" stripe><el-table-column prop="ticketNo" label="工单号" width="160"/><el-table-column label="类型" width="110"><template #default="{row}">{{types[row.type]||row.type}}</template></el-table-column><el-table-column prop="subject" label="主题" min-width="150"/><el-table-column prop="content" label="内容" min-width="230" show-overflow-tooltip/><el-table-column prop="contactPhone" label="联系方式" width="140"/><el-table-column label="状态" width="110"><template #default="{row}"><el-tag :type="tag(row.status)">{{statuses[row.status]}}</el-tag></template></el-table-column><el-table-column prop="createTime" label="提交时间" width="170"/><el-table-column label="处理" width="260" fixed="right"><template #default="{row}"><el-button v-if="row.status==='PENDING'" type="warning" @click="change(row,'PROCESSING')">开始处理</el-button><el-dropdown @command="s=>change(row,s)"><el-button type="primary">更新状态</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="RESOLVED">已解决</el-dropdown-item><el-dropdown-item command="REJECTED">已拒绝</el-dropdown-item><el-dropdown-item command="ARCHIVED">归档</el-dropdown-item></el-dropdown-menu></template></el-dropdown></template></el-table-column></el-table>
<el-pagination v-model:current-page="query.pageNum" :total="total" :page-size="20" layout="total, prev, pager, next" @current-change="load"/></div></template>
<script setup>import{reactive,ref,onMounted}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{adminApi}from'@/api/index';const types={CONTACT:'联系我们',DELETION:'注销申请',FEEDBACK:'用户反馈',CORRECTION:'数据纠错',COMPLAINT:'投诉建议'},statuses={PENDING:'待处理',PROCESSING:'处理中',RESOLVED:'已解决',REJECTED:'已拒绝',ARCHIVED:'已归档'};const query=reactive({pageNum:1,pageSize:20,type:'',status:'',keyword:''}),list=ref([]),total=ref(0),loading=ref(false);const tag=s=>({PENDING:'danger',PROCESSING:'warning',RESOLVED:'success',REJECTED:'info',ARCHIVED:'info'})[s];const load=async()=>{loading.value=true;try{const r=await adminApi.tickets(query);list.value=r.data||[];total.value=Number(r.total||0)}finally{loading.value=false}};const change=async(row,status)=>{let remark='';if(status!=='PROCESSING'){const r=await ElMessageBox.prompt('请填写处理意见','更新工单',{inputType:'textarea',confirmButtonText:'确认',cancelButtonText:'取消'});remark=r.value||''}await adminApi.transitionTicket(row.id,{status,remark});ElMessage.success('工单状态已更新');load()};onMounted(load)</script>
<style scoped>.page{background:#fff;padding:24px;border-radius:16px}.head{display:flex;justify-content:space-between}.head h2{margin:0}.head p{color:#64748b}.filters{display:grid;grid-template-columns:2fr 1fr 1fr auto;gap:12px;margin:18px 0}.el-pagination{justify-content:flex-end;margin-top:18px}</style>
